// --- WebGPU Global State ---
        let device, adapter, context;
        let computePipeline, renderPipeline;
        let uniformBuffer, workBuffer;
        let isStressTesting = false;
        let frameId;
        // --- Stats ---
        let frameCount = 0;
        let lastTime = 0;
        let fpsHistory = [];
        let peakFps = 0;
        let loadIntensity = 50; // 1 to 100
        // --- DOM ---
        const statusIndicator = document.getElementById('gpu-status-indicator');
        const statusText = document.getElementById('gpu-status-text');
        const gpuName = document.getElementById('gpu-name');
        const fpsVal = document.getElementById('fps-val');
        const stabilityVal = document.getElementById('stability-val');
        const vramBar = document.getElementById('vram-bar');
        const vramText = document.getElementById('vram-text');
        const canvas = document.getElementById('gpu-canvas');
        const graphCanvas = document.getElementById('graph-canvas');
        const graphCtx = graphCanvas.getContext('2d');
        // --- WGSL Shaders ---
        // A heavy compute shader to stress ALUs
        const computeShaderCode = `
            @group(0) @binding(0) var<storage, read_write> data: array<f32>;
            @group(0) @binding(1) var<uniform> params: vec2<f32>; // time, intensity
            @compute @workgroup_size(64)
            fn main(@builtin(global_invocation_id) global_id : vec3<u32>) {
                let index = global_id.x;
                if (index >= arrayLength(&data)) { return; }
                // Heavy math loop to simulate load
                var val = data[index];
                let loops = i32(params.y * 50.0); // Loop count based on intensity
                for (var i = 0; i < loops; i++) {
                    val = sin(val * params.x) * cos(val + f32(i));
                    val = sqrt(abs(val)) * 1.0001; 
                }
                data[index] = val;
            }
        `;
        // A visual shader to show activity
        const renderShaderCode = `
            struct Uniforms { time: f32, intensity: f32 };
            @group(0) @binding(0) var<uniform> u: Uniforms;
            struct VertexOutput { @builtin(position) Position : vec4<f32>, @location(0) uv : vec2<f32> };
            @vertex
            fn vs_main(@builtin(vertex_index) VertexIndex : u32) -> VertexOutput {
                var pos = array<vec2<f32>, 6>(
                    vec2(-1.0, -1.0), vec2(1.0, -1.0), vec2(-1.0, 1.0),
                    vec2(-1.0, 1.0), vec2(1.0, -1.0), vec2(1.0, 1.0)
                );
                var output : VertexOutput;
                output.Position = vec4(pos[VertexIndex], 0.0, 1.0);
                output.uv = pos[VertexIndex] * 0.5 + 0.5;
                return output;
            }
            @fragment
            fn fs_main(@location(0) uv : vec2<f32>) -> @location(0) vec4<f32> {
                let t = u.time;
                // Generate complex noise visual
                let x = uv.x * 10.0;
                let y = uv.y * 10.0;
                let v = sin(x + t) + cos(y - t) + sin(x * y + t);
                // Color ramp based on intensity
                let r = sin(v * 2.0) * 0.5 + 0.5;
                let g = cos(v * 3.0) * 0.5 + 0.5;
                let b = sin(v * 5.0 + t) * 0.5 + 0.5;
                return vec4(r, g, b, 1.0);
            }
        `;
        async function initWebGPU() {
            if (!navigator.gpu) {
                document.getElementById('error-msg').classList.remove('hidden');
                statusText.innerText = "Unsupported";
                return false;
            }
            adapter = await navigator.gpu.requestAdapter();
            if (!adapter) {
                statusText.innerText = "Adapter Error";
                return false;
            }
            // Get GPU Info if available (some browsers mask this for privacy)
            const info = await adapter.requestAdapterInfo();
            gpuName.innerText = info.device || "Generic WebGPU Adapter";
            device = await adapter.requestDevice();
            context = canvas.getContext('webgpu');
            const presentationFormat = navigator.gpu.getPreferredCanvasFormat();
            context.configure({
                device: device,
                format: presentationFormat,
                alphaMode: 'premultiplied',
            });
            // --- Setup Compute Pipeline ---
            const computeModule = device.createShaderModule({ code: computeShaderCode });
            computePipeline = device.createComputePipeline({
                layout: 'auto',
                compute: { module: computeModule, entryPoint: 'main' },
            });
            // Create a large buffer for VRAM stress (approx 64MB to start, can scale)
            // 16 million floats = 64MB
            const bufferSize = 16 * 1000 * 1000 * 4;
            workBuffer = device.createBuffer({
                size: bufferSize,
                usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
            });
            // --- Setup Render Pipeline ---
            const renderModule = device.createShaderModule({ code: renderShaderCode });
            renderPipeline = device.createRenderPipeline({
                layout: 'auto',
                vertex: { module: renderModule, entryPoint: 'vs_main' },
                fragment: { module: renderModule, entryPoint: 'fs_main', targets: [{ format: presentationFormat }] },
                primitive: { topology: 'triangle-list' },
            });
            uniformBuffer = device.createBuffer({
                size: 16, // vec2<f32> + padding is small, but alignment matters
                usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
            });
            statusText.innerText = "GPU Ready";
            statusIndicator.innerHTML = '<div class="w-2.5 h-2.5 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>';
            return true;
        }
        function updateLoad(val) {
            loadIntensity = parseInt(val);
            const maxMB = 512; // Visual scaling limit
            const currentMB = Math.floor((loadIntensity / 100) * maxMB);
            vramText.innerText = `~${currentMB} MB Active Data`;
            vramBar.style.width = `${loadIntensity}%`;
        }
        async function toggleStressTest() {
            const btn = document.getElementById('toggle-btn');
            const btnText = document.getElementById('btn-text');
            const btnIcon = document.getElementById('btn-icon');
            if (!device) {
                const success = await initWebGPU();
                if (!success) return;
            }
            if (isStressTesting) {
                // Stop
                isStressTesting = false;
                cancelAnimationFrame(frameId);
                btnText.innerText = "Ignite GPU Engine";
                btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path>';
                btn.classList.replace('bg-red-600', 'bg-purple-600');
                btn.classList.replace('hover:bg-red-700', 'hover:bg-purple-700');
                statusText.innerText = "GPU Idle";
            } else {
                // Start
                isStressTesting = true;
                fpsHistory = [];
                peakFps = 0;
                lastTime = performance.now();
                frameLoop();
                btnText.innerText = "Emergency Stop";
                btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>';
                btn.classList.replace('bg-purple-600', 'bg-red-600');
                btn.classList.replace('hover:bg-purple-700', 'hover:bg-red-700');
                statusText.innerText = "MAX LOAD";
            }
        }
        function frameLoop() {
            if (!isStressTesting) return;
            const now = performance.now();
            const dt = now - lastTime;
            lastTime = now;
            // FPS Calc
            const fps = 1000 / dt;
            updateStats(fps);
            // --- WebGPU Frame Encode ---
            const commandEncoder = device.createCommandEncoder();
            // 1. Update Uniforms
            const timeVal = now / 1000;
            const intensityVal = loadIntensity;
            const uniformData = new Float32Array([timeVal, intensityVal]);
            device.queue.writeBuffer(uniformBuffer, 0, uniformData);
            // 2. Dispatch Compute (Stress)
            // Scaling workgroups based on intensity slider
            const workgroups = Math.max(1, Math.floor((loadIntensity / 100) * 1000));
            const computePass = commandEncoder.beginComputePass();
            computePass.setPipeline(computePipeline);
            // Need bind group creation inside loop or cached. For simplicity creating inline (not optimal but good for stress!)
            const computeBindGroup = device.createBindGroup({
                layout: computePipeline.getBindGroupLayout(0),
                entries: [
                    { binding: 0, resource: { buffer: workBuffer } },
                    { binding: 1, resource: { buffer: uniformBuffer } },
                ],
            });
            computePass.setBindGroup(0, computeBindGroup);
            computePass.dispatchWorkgroups(workgroups);
            computePass.end();
            // 3. Render Visuals
            const renderPass = commandEncoder.beginRenderPass({
                colorAttachments: [{
                    view: context.getCurrentTexture().createView(),
                    clearValue: { r: 0, g: 0, b: 0, a: 1 },
                    loadOp: 'clear',
                    storeOp: 'store',
                }],
            });
            renderPass.setPipeline(renderPipeline);
            const renderBindGroup = device.createBindGroup({
                layout: renderPipeline.getBindGroupLayout(0),
                entries: [{ binding: 0, resource: { buffer: uniformBuffer } }]
            });
            renderPass.setBindGroup(0, renderBindGroup);
            renderPass.draw(6); // Draw quad
            renderPass.end();
            device.queue.submit([commandEncoder.finish()]);
            frameId = requestAnimationFrame(frameLoop);
        }
        function updateStats(fps) {
            if (!fps || !isFinite(fps)) return;
            // Smoothing
            if (fpsHistory.length > 50) fpsHistory.shift();
            fpsHistory.push(fps);
            const avgFps = fpsHistory.reduce((a, b) => a + b, 0) / fpsHistory.length;
            fpsVal.innerText = Math.round(avgFps);
            // Peak tracking for throttling detection
            if (avgFps > peakFps) peakFps = avgFps;
            // Stability Calc (Current vs Peak)
            // Allow some warmup time (first 100 frames ignored for peak lock)
            if (peakFps > 0) {
                let stability = (avgFps / peakFps) * 100;
                if (stability > 100) stability = 100;
                stabilityVal.innerText = Math.round(stability) + "%";
                if (stability < 70) stabilityVal.className = "text-xl md:text-3xl font-bold text-red-500 animate-pulse";
                else if (stability < 90) stabilityVal.className = "text-xl md:text-3xl font-bold text-amber-400";
                else stabilityVal.className = "text-xl md:text-3xl font-bold text-emerald-400";
            }
            drawGraph();
        }
        function drawGraph() {
            const w = graphCanvas.width = graphCanvas.clientWidth;
            const h = graphCanvas.height = graphCanvas.clientHeight;
            graphCtx.clearRect(0, 0, w, h);
            graphCtx.beginPath();
            graphCtx.strokeStyle = "#8b5cf6";
            graphCtx.lineWidth = 2;
            if (fpsHistory.length < 2) return;
            const step = w / 50; // display last 50 pts
            // Normalize graph height to roughly 144hz or peak
            const maxGraphFps = Math.max(peakFps, 60) * 1.2;
            fpsHistory.forEach((val, i) => {
                const x = i * step;
                const y = h - ((val / maxGraphFps) * h);
                if (i === 0) graphCtx.moveTo(x, y);
                else graphCtx.lineTo(x, y);
            });
            graphCtx.stroke();
        }
        // --- SCROLL LOGIC ---
        // Auto init VRAM bar on load
        updateLoad(50);
